#include <iostream>
#include <fstream>
#include <string>
#include <omniORB4/CORBA.h>

#include "message.hh" // Generated by the IDL compiler

class Echo_i : public virtual POA_MessageModule::Echo {
public:
    virtual ~Echo_i() {}

    virtual MessageModule::MyMessage* echoMessage(const MessageModule::MyMessage& msg) override {
        std::cout << "Received message: ID=" << msg.id << ", Text=" << msg.text << std::endl;
        MessageModule::MyMessage* result = new MessageModule::MyMessage;
        result->id = msg.id;
        result->text = CORBA::string_dup(msg.text); // duplicate string
        return result;
    }
};

int main(int argc, char* argv[]) {
    try {
        CORBA::ORB_var orb = CORBA::ORB_init(argc, argv);
        CORBA::Object_var obj = orb->resolve_initial_references("RootPOA");
        PortableServer::POA_var root_poa = PortableServer::POA::_narrow(obj);
        if (CORBA::is_nil(root_poa)) {
            std::cerr << "Could not resolve RootPOA." << std::endl;
            return 1;
        }
        PortableServer::POAManager_var poa_manager = root_poa->the_POAManager();
        poa_manager->activate();
        Echo_i* echo_impl = new Echo_i();
        PortableServer::ServantBase_var servant_var(echo_impl);
        MessageModule::Echo_var echo_ref = echo_impl->_this();
        CORBA::String_var ior = orb->object_to_string(echo_ref);
        std::cout << "Echo server IOR: " << ior.in() << std::endl;
        std::ofstream ior_file("message.ior", std::ofstream::out);
        if (ior_file.is_open()) {
            ior_file << ior.in();
            ior_file.close();
            std::cout << "IOR written to message.ior" << std::endl;
        } else {
            std::cerr << "Unable to open message.ior file" << std::endl;
        }
        orb->run();
        root_poa->destroy(true, true);
        orb->destroy();
    } catch (CORBA::Exception& ex) {
        std::cerr << "CORBA exception: " << ex._name() << std::endl;
        return 1;
    }
    return 0;
}

